        if ncost >= 2
            % C1 is located at column (end-1)
            c1_col = size(mpc.gencost, 2) - 1;
            mpc.gencost(gc_idx, c1_col) = mpc.gencost(gc_idx, c1_col) * 0.8;
        end
    end
